function checkWebhookRateLimit(ip) {
  const now = Date.now();
  const windowMs = 1e4;
  const maxReqs = 20;
  const rec = webhookRateLimiter.get(ip) || { count: 0, resetAt: now + windowMs };
  if (now > rec.resetAt) {
    rec.count = 0;
    rec.resetAt = now + windowMs;
  }
  rec.count++;
  webhookRateLimiter.set(ip, rec);
  if (rec.count > maxReqs) {
    return { limited: true, retryAfter: Math.ceil((rec.resetAt - now) / 1e3) };
  }
  return { limited: false };
}
