function hashSimpleSha2(password) {
  return crypto.subtle.digest("SHA-256", new TextEncoder().encode(password)).then((buf) => {
    return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
  });
}
