async function checkAuth24(request, env) {
  const PASS = env.ADMIN_PASSWORD || "pr2026";
  const authHeader = request.headers.get("Authorization") || "";
  const cookieHeader = request.headers.get("Cookie") || "";
  let token = null;
  if (authHeader.startsWith("Bearer ")) {
    token = authHeader.slice(7).trim();
  } else {
    const match2 = cookieHeader.match(/pr_admin_token=([^;]+)/);
    if (match2) token = match2[1];
  }
  if (token) {
    const payload = await verifyAdminToken(token, env);
    if (payload) return true;
  }
  if (authHeader.startsWith("Basic ")) {
    try {
      const base64 = authHeader.slice(6).trim();
      const decoded = atob(base64);
      const colonIdx = decoded.indexOf(":");
      if (colonIdx !== -1) {
        return decoded.slice(colonIdx + 1) === PASS;
      }
    } catch (e) {
      return false;
    }
  }
  return false;
}
